#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* Encrypted storage database driver - handles page-level encryption */

#define PAGE_SIZE 4096
#define HEADER_SIZE 64
#define MAC_SIZE 32
#define MAX_RECORD_COUNT 65535

typedef struct {
    uint32_t magic;
    uint16_t version;
    uint16_t flags;
    uint32_t page_count;
    uint32_t record_count;
    uint8_t  iv[16];
    uint8_t  reserved[32];
} __attribute__((packed)) db_header_t;

typedef struct {
    uint16_t key_len;
    uint16_t val_len;
    uint32_t flags;
    uint32_t checksum;
} __attribute__((packed)) record_header_t;

typedef struct {
    uint8_t *pages;
    size_t   total_size;
    uint32_t num_pages;
    uint8_t  encryption_key[32];
    int      authenticated;
} db_context_t;

/* Simplified XOR-based encryption for demonstration */
static void encrypt_block(uint8_t *dst, const uint8_t *src, size_t len, const uint8_t *key) {
    for (size_t i = 0; i < len; i++) {
        dst[i] = src[i] ^ key[i % 32];
    }
}

static uint32_t compute_checksum(const uint8_t *data, size_t len) {
    uint32_t crc = 0xFFFFFFFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc = (crc >> 1) ^ (0xEDB88320 & (-(crc & 1)));
        }
    }
    return crc ^ 0xFFFFFFFF;
}

/* Calculate total buffer size needed for batch insert.
 * Each record needs: record_header + key_data + value_data + MAC
 * We also add per-record alignment padding to 8-byte boundary.
 */
static size_t calculate_batch_buffer_size(uint16_t num_records,
                                          const uint16_t *key_lengths,
                                          const uint16_t *val_lengths) {
    size_t total = 0;
    for (uint16_t i = 0; i < num_records; i++) {
        /* record_header_t is 12 bytes */
        size_t record_payload = (size_t)key_lengths[i] + (size_t)val_lengths[i];
        /* Align each record to 8 bytes for encryption block alignment */
        size_t record_size = sizeof(record_header_t) + record_payload + MAC_SIZE;
        size_t aligned_size = (record_size + 7) & ~(size_t)7;
        total += aligned_size;
    }
    return total;
}

/* Allocate encrypted page buffer for batch write.
 * The critical calculation: we need pages to hold all records plus
 * per-page headers and authentication tags.
 */
static uint8_t *allocate_encrypted_pages(uint16_t num_records,
                                          const uint16_t *key_lengths,
                                          const uint16_t *val_lengths,
                                          uint32_t *out_num_pages) {
    size_t data_size = calculate_batch_buffer_size(num_records, key_lengths, val_lengths);

    /* Each page has HEADER_SIZE overhead for page-level auth metadata */
    size_t usable_per_page = PAGE_SIZE - HEADER_SIZE;

    /* Calculate number of pages needed */
    size_t pages_needed = (data_size + usable_per_page - 1) / usable_per_page;

    /* Total allocation: pages_needed * PAGE_SIZE
     * Use size_t arithmetic throughout to prevent overflow.
     */
    size_t alloc_size = pages_needed * (size_t)PAGE_SIZE;

    /* Safety check: ensure we don't allocate more than 2GB */
    if (alloc_size > 0x7FFFFFFF || alloc_size == 0 || pages_needed > UINT32_MAX) {
        return NULL;
    }

    *out_num_pages = (uint32_t)pages_needed;
    uint8_t *buffer = (uint8_t *)calloc(1, alloc_size);
    return buffer;
}

/* Write records into the encrypted page buffer */
static int write_records_to_pages(uint8_t *page_buffer,
                                   uint32_t num_pages,
                                   uint16_t num_records,
                                   const uint8_t **keys,
                                   const uint16_t *key_lengths,
                                   const uint8_t **values,
                                   const uint16_t *val_lengths,
                                   const uint8_t *enc_key) {
    size_t write_offset = 0;
    uint32_t current_page = 0;
    size_t page_offset = HEADER_SIZE; /* skip page header */

    for (uint16_t i = 0; i < num_records; i++) {
        record_header_t hdr;
        hdr.key_len = key_lengths[i];
        hdr.val_len = val_lengths[i];
        hdr.flags = 0;

        size_t record_payload = (size_t)key_lengths[i] + (size_t)val_lengths[i];
        size_t record_size = sizeof(record_header_t) + record_payload + MAC_SIZE;
        size_t aligned_size = (record_size + 7) & ~(size_t)7;

        /* Check if record fits in current page */
        if (page_offset + aligned_size > PAGE_SIZE) {
            current_page++;
            page_offset = HEADER_SIZE;
            if (current_page >= num_pages) {
                return -1;
            }
        }

        write_offset = (size_t)current_page * PAGE_SIZE + page_offset;

        /* Compute checksum over key+value */
        uint8_t *temp = (uint8_t *)malloc(record_payload);
        if (!temp) return -1;
        memcpy(temp, keys[i], key_lengths[i]);
        memcpy(temp + key_lengths[i], values[i], val_lengths[i]);
        hdr.checksum = compute_checksum(temp, record_payload);
        free(temp);

        /* Write encrypted record header */
        encrypt_block(page_buffer + write_offset, (uint8_t *)&hdr,
                     sizeof(record_header_t), enc_key);
        write_offset += sizeof(record_header_t);

        /* Write encrypted key */
        encrypt_block(page_buffer + write_offset, keys[i], key_lengths[i], enc_key);
        write_offset += key_lengths[i];

        /* Write encrypted value */
        encrypt_block(page_buffer + write_offset, values[i], val_lengths[i], enc_key);
        write_offset += val_lengths[i];

        page_offset += aligned_size;
    }

    return 0;
}

/* Public API: batch insert records into encrypted database */
int db_batch_insert(db_context_t *ctx,
                    uint16_t num_records,
                    const uint8_t **keys,
                    const uint16_t *key_lengths,
                    const uint8_t **values,
                    const uint16_t *val_lengths) {
    if (!ctx || !ctx->authenticated) {
        return -1;
    }
    if (num_records == 0 || num_records > MAX_RECORD_COUNT) {
        return -1;
    }

    /* Validate individual record sizes */
    for (uint16_t i = 0; i < num_records; i++) {
        if (key_lengths[i] == 0 || val_lengths[i] == 0) {
            return -1;
        }
        /* Each record must fit within a single page's usable space */
        size_t rec_total = sizeof(record_header_t) + (size_t)key_lengths[i] +
                            (size_t)val_lengths[i] + MAC_SIZE;
        if (rec_total > (PAGE_SIZE - HEADER_SIZE)) {
            return -1;
        }
    }

    uint32_t num_pages = 0;
    uint8_t *page_buffer = allocate_encrypted_pages(num_records, key_lengths,
                                                     val_lengths, &num_pages);
    if (!page_buffer) {
        return -1;
    }

    int result = write_records_to_pages(page_buffer, num_pages, num_records,
                                         keys, key_lengths, values, val_lengths,
                                         ctx->encryption_key);

    if (result == 0) {
        /* Append pages to database storage */
        size_t new_size = ctx->total_size + (size_t)num_pages * PAGE_SIZE;
        uint8_t *new_pages = (uint8_t *)realloc(ctx->pages, new_size);
        if (new_pages) {
            memcpy(new_pages + ctx->total_size, page_buffer,
                   (size_t)num_pages * PAGE_SIZE);
            ctx->pages = new_pages;
            ctx->total_size = new_size;
            ctx->num_pages += num_pages;
        } else {
            result = -1;
        }
    }

    free(page_buffer);
    return result;
}
